using AetherGrid.Core;
using System.Text.Json.Nodes;
using System.Text.Json;
using System.Text;
using System.Globalization;
using System.Security.Cryptography;
namespace AetherGrid.Server;
public sealed class Workflow(Store store,IConfiguration config)
{
 public JsonObject Catalog{get;}=JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"catalog.json")))!.AsObject();
 public Commodity Profile(string commodity){var p=Catalog["profiles"]?[commodity]?.AsObject()??throw new ApiError("Unknown commodity");return new(p.N("shelf_hours_ref"),p.N("q10"),p.N("opt_temp_c"),p.N("max_safe_temp_c"),p.N("eth_sensitivity"),p.N("wholesale_price_inr_per_kg"));}
 public static double Km(double a,double b,double c,double d){double R(double v)=>v*Math.PI/180;var h=Math.Pow(Math.Sin(R(c-a)/2),2)+Math.Cos(R(a))*Math.Cos(R(c))*Math.Pow(Math.Sin(R(d-b)/2),2);return 12742*Math.Asin(Math.Sqrt(Math.Clamp(h,0,1)));}
 public int AuctionSeconds=>Math.Clamp(config.GetValue("AETHER_AUCTION_SECONDS",900),1,3600);
 public int ReviewSeconds=>Math.Clamp(config.GetValue("AETHER_REVIEW_SECONDS",120),1,900);
 public bool Active(JsonObject b)=>new[]{"InTransit","DistressedLiquidation","Rerouted"}.Contains(b.S("status"));
 public void Audit(Tx tx,string kind,string lot,string description,string severity="ok"){var data=new JsonObject{["kind"]=kind,["batch_id"]=lot,["description"]=description,["severity"]=severity};if(kind is "spoiled" or "delivered"){var b=tx.Get("batch",lot);data["commodity"]=b?.S("commodity")??"Cargo";data["lat"]=b?.N("lat")??0;data["lng"]=b?.N("lng")??0;data["destination"]=b?.S("destination_name")??"Destination";data["life_consumed_pct"]=b?.N("life_consumed_pct")??0;}tx.Event(kind,lot,data);}
 public object Provision(JsonObject data,string actor)=>store.Write(tx=>{
  string kind=data.S("kind");J.Require(new[]{"buyer","carrier","truck","batch","api_key","user"}.Contains(kind),"Unknown provision kind");var obj=data["record"]?.AsObject()??throw new ApiError("record required");var id=obj.S("id");J.Require(id.Length is >=3 and <=120,"Identifier required");J.Require(tx.Get(kind,id) is null,"Already exists",409);
  if(kind=="buyer"){J.Require(obj.N("capacity_kg")>0&&obj.N("service_radius_km")>0&&obj.N("simulated_escrow_inr")>=0,"Invalid buyer resources");Coordinates(obj.N("lat"),obj.N("lng"));J.Require(obj["accepted_commodities"] is JsonArray,"Explicit commodity policy required");obj["pre_authorized"]=obj.B("pre_authorized");}
  if(kind=="truck"){tx.Need("carrier",obj.S("carrier_id"));J.Require(obj.S("hsm_serial").Length>=3,"Signing serial required");J.Require(!tx.All("truck").Any(t=>t.S("hsm_serial")==obj.S("hsm_serial")),"Duplicate serial",409);}
  if(kind=="batch"){
   var p=Profile(obj.S("commodity"));var truck=tx.Need("truck",obj.S("truck_id"));J.Require(!tx.All("batch").Any(b=>b.S("truck_id")==truck.S("id")&&Active(b)),"Truck already has active cargo",409);J.Require(obj.N("weight_kg") is >10 and <=50000&&obj.N("contract_value_inr")>0,"Invalid lot");Coordinates(obj.N("origin_lat"),obj.N("origin_lng"));Coordinates(obj.N("dest_lat"),obj.N("dest_lng"));obj["commodity_key"]=obj.S("commodity");obj["status"]="InTransit";obj["carrier_id"]=truck.S("carrier_id");obj["health"]="fresh";obj["life_consumed_pct"]=0;obj["farmer_payout_inr"]=0;obj["lat"]=obj.N("origin_lat");obj["lng"]=obj.N("origin_lng");obj["reroute_count"]=0;obj["created_at"]=J.Now();obj["sum_assured_inr"]=obj.N("contract_value_inr")*.6;obj["cover_pct"]=.45;obj["deductible_pct"]=.05;
  }
  if((kind=="user"||kind=="api_key")&&obj.S("role")=="buyer")tx.Need("buyer",obj.S("buyer_id"));
  if(kind=="api_key"&&obj.S("role")=="device")tx.Need("truck",obj.S("truck_id"));
  if(kind=="api_key"){J.Require(obj.N("expires_at")>J.Epoch()&&new[]{"device","operator","auditor","buyer"}.Contains(obj.S("role")),"Invalid API key");J.Require(id.Length==64&&id.All(Uri.IsHexDigit),"API-key ID must be SHA256 digest");}
  if(kind=="user"){J.Require(Security.ValidHash(obj.S("password_hash")),"Hash required; plaintext passwords not accepted");J.Require(new[]{"operator","auditor","buyer"}.Contains(obj.S("role")),"Invalid role");obj["username"]=id;obj["version"]=1;obj["disabled"]=false;}
  tx.Put(kind,id,obj);Audit(tx,"provisioned",kind+":"+id,"Provisioned by "+actor+"; record is an operator assertion.");return new{status="provisioned",kind,id};
 });
 public static void Coordinates(double lat,double lng)=>J.Require(double.IsFinite(lat)&&double.IsFinite(lng)&&Math.Abs(lat)<=90&&Math.Abs(lng)<=180,"Invalid coordinates");
 public object Baseline(string lot,JsonObject p,string actor)=>store.Write(tx=>{var b=tx.Need("batch",lot);J.Require(b.S("status")=="InTransit"&&tx.Get("checkpoint",lot) is null&&!tx.All("sample").Any(s=>s.S("batch_id")==lot),"Cannot reset model history",409);var ts=p.N("reference_timestamp");J.Require(ts>0&&ts<=J.Epoch()&&p.N("initial_life_consumed") is >=0 and <=1.5&&p.N("hours_out_of_range")>=0&&p.S("evidence_note").Length>=20&&p.S("reference").Length>=8,"Invalid reviewed baseline");J.Require(!tx.All("baseline").Any(x=>x.S("reference")==p.S("reference")),"Reference reused",409);p["asserted_by"]=actor;tx.Put("baseline",lot,p);tx.Put("checkpoint",lot,new JsonObject{["life"]=p.N("initial_life_consumed"),["oor"]=p.N("hours_out_of_range"),["max_t"]=0,["max_e"]=0});Audit(tx,"baseline",lot,"Operator-reviewed baseline, not independent quality verification.");return new{status="operator_baseline_recorded",independently_verified=false};});
 public static JsonObject Normalize(JsonObject p){var f=new JsonObject();foreach(var k in new[]{"hsm_serial","batch_id","truck_id"})f[k]=p.S(k);foreach(var k in new[]{"seq","ts","signature_version"}){var n=p.N(k,k=="signature_version"?1:0);J.Require(double.IsFinite(n)&&n>=0&&n<=9007199254740991&&Math.Floor(n)==n,"Invalid integer field "+k);f[k]=(long)n;}foreach(var k in new[]{"lat","lng","temp_c","humidity_pct","ethylene_ppm","speed_kmh"})f[k]=p.N(k);foreach(var k in new[]{"reefer_setpoint_c","fuel_level_pct","cellular_rssi"})f[k]=p[k] is null?null:p.N(k);f["door_open"]=p.B("door_open");f["in_dead_zone"]=p.B("in_dead_zone");return f;}
 public static string Canonical(JsonObject normalized){string V(KeyValuePair<string,JsonNode?> v){if(v.Value is null)return "null";if(new[]{"seq","ts","signature_version"}.Contains(v.Key)||v.Value.GetValueKind()!=JsonValueKind.Number)return v.Value.ToJsonString(new JsonSerializerOptions{Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping});var n=v.Value.GetValue<double>();var s=n.ToString("R",CultureInfo.InvariantCulture).ToLowerInvariant();if(!s.Contains('.')&&!s.Contains('e'))s+=".0";return s;}return "{"+string.Join(",",normalized.OrderBy(x=>x.Key,StringComparer.Ordinal).Select(k=>JsonSerializer.Serialize(k.Key)+":"+V(k)))+"}";}
 public object Telemetry(JsonObject packet,Actor actor)=>store.Write(tx=>{
  var p=Normalize(packet);var lot=p.S("batch_id");var b=tx.Need("batch",lot);var truck=tx.Need("truck",p.S("truck_id"));J.Require(Active(b),"Telemetry lot is terminal",409);J.Require(actor.Role=="operator"||(actor.Role=="device"&&actor.TruckId==p.S("truck_id")),"Device identity mismatch",403);J.Require(truck.S("hsm_serial")==p.S("hsm_serial")&&b.S("truck_id")==truck.S("id"),"Telemetry binding mismatch",403);
  Coordinates(p.N("lat"),p.N("lng"));J.Require(p.N("temp_c") is >=-80 and <=100&&p.N("humidity_pct") is >=0 and <=100&&p.N("ethylene_ppm") is >=0 and <=10000&&p.N("seq")>=0,"Invalid readings");J.Require(p.N("signature_version")==2,"Version-2 signing required");
  var roots=new List<string>();var keysFile=config["AETHER_SIGNING_KEYS_FILE"];
  if(string.IsNullOrEmpty(keysFile))roots.Add(config["AETHER_TELEMETRY_ROOT"]!);else {var keyring=JsonNode.Parse(File.ReadAllText(keysFile))!.AsObject();if(keyring[p.S("hsm_serial")] is JsonArray keys)foreach(var node in keys){var key=node!.AsObject();if(key.S("root").Length>=32&&key.N("not_after")>J.Epoch())roots.Add(key.S("root"));}}
  J.Require(roots.Any(root=>Security.Same("AG2-"+Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(root+"|"+p.S("hsm_serial")),Encoding.UTF8.GetBytes(Canonical(p)))).ToLowerInvariant(),packet.S("hsm_signature"))),"Invalid signature",403);J.Require(Math.Abs(J.Epoch()-p.N("ts"))<=120,"Stale reading");var cursor=tx.Get("cursor",truck.S("id"));J.Require(cursor is null||p.N("seq")>cursor.N("seq"),"Replayed sequence",409);
  var baseline=tx.Need("baseline",lot);var cp=tx.Need("checkpoint",lot);var previous=Math.Max(baseline.N("reference_timestamp"),cursor?.N("ts")??0);var delta=p.N("ts")-previous;J.Require(delta is >=0 and <=120,"Exposure gap/regression requires review");var timer=new BioTimer(Profile(b.S("commodity")));timer.Restore(cp.N("life"),cp.N("oor"),cp.N("max_t"),cp.N("max_e"));timer.Apply(p.N("temp_c"),p.N("humidity_pct"),p.N("ethylene_ppm"),delta/3600,p.B("door_open"));var ett=Km(p.N("lat"),p.N("lng"),b.N("dest_lat"),b.N("dest_lng"))/42;var snap=timer.Snapshot(p.N("temp_c"),p.N("humidity_pct"),p.N("ethylene_ppm"),ett);
  tx.Put("checkpoint",lot,new JsonObject{["life"]=timer.LifeConsumed,["oor"]=timer.HoursOutOfRange,["max_t"]=timer.MaxTemp,["max_e"]=timer.MaxEthylene});tx.Put("cursor",truck.S("id"),new JsonObject{["seq"]=p.N("seq"),["ts"]=p.N("ts")});b["lat"]=p.N("lat");b["lng"]=p.N("lng");b["temp_c"]=p.N("temp_c");b["rvh_hours"]=J.R(snap.Rvh);b["ett_hours"]=J.R(ett);b["ett_to_original_dest_hours"]=J.R(ett);b["life_consumed_pct"]=snap.LifeConsumed*100;b["health"]=snap.Health;truck["last_heartbeat"]=J.Now();
  if(Active(b)&&snap.Health=="spoiled"){b["status"]="Spoiled";Audit(tx,"spoiled",lot,"Model spoiled; no physical quality verification.","critical");}
  else if(Active(b)&&Km(p.N("lat"),p.N("lng"),b.N("dest_lat"),b.N("dest_lng"))<2){b["status"]="Delivered";Audit(tx,"delivered",lot,"Model arrived at original destination; not physical receipt.");}
  else if(b.S("status")=="InTransit"&&(p.N("temp_c")>Profile(b.S("commodity")).MaxSafeTemp-2||snap.Health is "aging" or "critical")&&snap.Rvh<3*ett){b["status"]="DistressedLiquidation";OpenAuction(tx,b,0,null,snap.Rvh);}
  if(Active(b)){var options=new Routing(this).Operational(tx,b);b["route_options"]=options;var best=options.Select(n=>n!.AsObject()).FirstOrDefault(x=>x.N("expected_spoilage_pct")<100);b["best_plan"]=best?.Copy();if(best is not null&&config["AETHER_AUTO_MODEL_ROUTING"]=="true"&&(b["routing_target"] is not JsonObject oldTarget||oldTarget.S("target_id")!=best.S("target_id")||oldTarget.S("plan_type")!=best.S("plan_type"))){b["routing_target"]=best.Copy();b["reroute_count"]=b.N("reroute_count")+1;tx.Event("automatic_model_reroute",lot,new JsonObject{["target_id"]=best.S("target_id"),["plan_type"]=best.S("plan_type"),["physical_dispatch"]=false,["life_reset"]=false});}}
  tx.Put("truck",truck.S("id"),truck);tx.Put("batch",lot,b);var sample=p.Copy();sample["ts"]=DateTimeOffset.FromUnixTimeSeconds((long)p.N("ts")).ToString("O");sample["temp"]=p.N("temp_c");sample["h"]=p.N("humidity_pct");sample["life"]=b.N("life_consumed_pct");sample["rvh"]=b.N("rvh_hours");sample["door"]=p.B("door_open");tx.Put("sample",truck.S("id")+":"+p.N("seq"),sample);tx.Event("telemetry",lot,new JsonObject{["batch_id"]=lot,["status"]=b.S("status"),["rvh_hours"]=b.N("rvh_hours"),["lat"]=b.N("lat"),["lng"]=b.N("lng"),["temp_c"]=b.N("temp_c"),["life_consumed_pct"]=b.N("life_consumed_pct"),["health"]=b.S("health"),["spoil_eta_hours"]=snap.SpoilEta});return new{ok=true,batch_status=b.S("status"),snapshot=new{rvh_hours=J.R(snap.Rvh),spoil_eta_hours=J.R(snap.SpoilEta),life_consumed_pct=J.R(snap.LifeConsumed*100),health=snap.Health,time_to_distress_hours=snap.TimeToDistress}};
 });
 public JsonObject OpenAuction(Tx tx,JsonObject b,int attempt,string? parent,double rvh){var id=J.Id("F-");var a=new JsonObject{["id"]=id,["batch_id"]=b.S("id"),["commodity"]=b.S("commodity"),["status"]="Open",["opens_at"]=J.Now(),["closes_at"]=DateTimeOffset.UtcNow.AddSeconds(attempt==0?AuctionSeconds:ReviewSeconds).ToString("O"),["trigger_lat"]=b.N("lat"),["trigger_lng"]=b.N("lng"),["trigger_temp_c"]=b.N("temp_c"),["trigger_rvh_hours"]=rvh,["lot_kg"]=b.N("weight_kg"),["attempt"]=attempt,["parent_id"]=parent};tx.Put("auction",id,a);Audit(tx,"auction_opened",b.S("id"),"Time-boxed simulated rescue transaction opened.","critical");tx.Event("distressed",b.S("id"),new JsonObject{["auction_id"]=id,["batch_id"]=b.S("id"),["commodity"]=b.S("commodity"),["rvh_hours"]=rvh,["ett_hours"]=b.N("ett_hours"),["nearby_buyers"]=new JsonArray()});return a;}
 public object Bid(string id,JsonObject p,Actor actor)=>store.Write(tx=>{var a=tx.Need("auction",id);var b=tx.Need("batch",a.S("batch_id"));J.Require(a.S("status")=="Open"&&b.S("status")=="DistressedLiquidation","Auction unavailable",409);var buyer=tx.Need("buyer",p.S("buyer_id"));J.Require(actor.Role=="operator"||(actor.Role=="buyer"&&actor.BuyerId==buyer.S("id")),"Buyer binding mismatch",403);var price=p.N("price_inr_per_kg");var kg=p.N("kg_requested");J.Require(price is >1 and <=5000&&kg is >10 and <=50000,"Invalid bid");var remaining=Math.Max(0,Math.Min(a.N("trigger_rvh_hours"),b.N("rvh_hours"))-(DateTimeOffset.UtcNow-DateTimeOffset.Parse(a.S("opens_at"))).TotalHours);var rejected=Eligibility.Reject(new(b.S("commodity"),b.N("weight_kg"),kg,price,buyer.N("capacity_kg"),buyer["accepted_commodities"]!.AsArray().Select(x=>x!.GetValue<string>()).ToArray(),buyer.N("simulated_escrow_inr"),Km(a.N("trigger_lat"),a.N("trigger_lng"),buyer.N("lat"),buyer.N("lng")),buyer.N("service_radius_km"),80,remaining,buyer.B("pre_authorized"),DateTimeOffset.UtcNow>=DateTimeOffset.Parse(a.S("closes_at"))));J.Require(rejected.Length==0,string.Join(",",rejected));buyer["capacity_kg"]=buyer.N("capacity_kg")-kg;buyer["simulated_escrow_inr"]=buyer.N("simulated_escrow_inr")-price*kg;tx.Put("buyer",buyer.S("id"),buyer);p["placed_at"]=J.Now();a["bid"]=p;a["status"]="AwaitingConfirmation";a["confirmation_deadline"]=DateTimeOffset.UtcNow.AddSeconds(ReviewSeconds).ToString("O");a["winning_buyer_name"]=buyer.S("name");a["winning_price_inr_per_kg"]=price;tx.Put("auction",id,a);Audit(tx,"awaiting_confirmation",b.S("id"),"Simulated resources reserved; operator confirmation required.","warn");tx.Event("auction_pending",b.S("id"),new JsonObject{["auction_id"]=id});return new{status="awaiting_confirmation",mode="simulated"};});
 public object Confirm(string id,JsonObject p,Actor actor)=>store.Write<object>(tx=>{var a=tx.Need("auction",id);var b=tx.Need("batch",a.S("batch_id"));J.Require(a.S("status")=="AwaitingConfirmation","Not awaiting confirmation",409);J.Require(p.S("action") is "confirm" or "reject","Invalid action");J.Require(p.B("simulated_escrow_acknowledged"),"Explicit simulation acknowledgement required");if(p.S("action")=="reject"||b.S("status")!="DistressedLiquidation"||DateTimeOffset.Parse(a.S("confirmation_deadline"))<=DateTimeOffset.UtcNow){Retry(tx,a,b,"Rejected/expired/unavailable");return new{status="released",mode="simulated"};}var bid=a["bid"]!.AsObject();var cp=tx.Need("checkpoint",b.S("id"));var profile=Profile(b.S("commodity"));var carrier=tx.Get("carrier",b.S("carrier_id"));var doors=tx.All("sample").Count(s=>s.S("batch_id")==b.S("id")&&s.B("door"));var n=Settlement.Compute(new(profile.Wholesale,b.N("weight_kg"),b.N("contract_value_inr"),b.N("sum_assured_inr"),b.N("cover_pct"),b.N("deductible_pct"),bid.N("price_inr_per_kg"),bid.N("kg_requested"),b.N("life_consumed_pct"),cp.N("oor"),doors,carrier?.N("sla_compliance_pct",96)??96));var s=new JsonObject{["id"]=J.Id("S-"),["batch_id"]=b.S("id"),["auction_id"]=id,["buyer_id"]=bid.S("buyer_id"),["kg_cleared"]=bid.N("kg_requested"),["price_inr_per_kg"]=bid.N("price_inr_per_kg"),["salvage_revenue_inr"]=J.R(n.Salvage),["insurance_payout_inr"]=J.R(n.Insurance),["logistics_penalty_inr"]=J.R(n.Penalty),["farmer_total_payout_inr"]=J.R(n.Farmer),["farmer_recovery_pct"]=J.R(n.RecoveryPct),["buyer_savings_pct"]=J.R(n.BuyerSavingsPct),["settled_at"]=J.Now(),["confirmed_by"]=actor.Subject,["mode"]="simulated"};var evidence=new JsonObject{["settlement"]=s.Copy(),["samples"]=new JsonArray(tx.All("sample").Where(x=>x.S("batch_id")==b.S("id")).Select(x=>(JsonNode)x).ToArray()),["baseline"]=tx.Need("baseline",b.S("id"))};s["evidence_hash"]=Security.Hash(evidence.ToJsonString());tx.Put("evidence",s.S("id"),evidence);tx.Put("settlement",b.S("id"),s);b["status"]="Cleared";b["farmer_payout_inr"]=J.R(n.Farmer);a["status"]="Settled";tx.Put("batch",b.S("id"),b);tx.Put("auction",id,a);Audit(tx,"settled",b.S("id"),"Simulated ledger only; farmer credit ₹"+J.R(n.Farmer));var ev=s.Copy();ev["commodity"]=b.S("commodity");ev["buyer_name"]=a.S("winning_buyer_name");ev["farmer_payout_rs"]=n.Farmer;ev["price_per_kg"]=bid.N("price_inr_per_kg");tx.Event("auction_settled",b.S("id"),ev);return new{status="won",mode="simulated",settlement=s};});
 public void Retry(Tx tx,JsonObject a,JsonObject b,string why){if(a.S("status") is not ("Open" or "AwaitingConfirmation"))return;if(a.S("status")=="AwaitingConfirmation"){var bid=a["bid"]!.AsObject();var buyer=tx.Need("buyer",bid.S("buyer_id"));buyer["capacity_kg"]=buyer.N("capacity_kg")+bid.N("kg_requested");buyer["simulated_escrow_inr"]=buyer.N("simulated_escrow_inr")+bid.N("price_inr_per_kg")*bid.N("kg_requested");tx.Put("buyer",buyer.S("id"),buyer);}a["status"]="Expired";tx.Put("auction",a.S("id"),a);Audit(tx,"auction_expired",b.S("id"),why,"warn");var rvh=Math.Max(0,Math.Min(a.N("trigger_rvh_hours"),b.N("rvh_hours"))-(DateTimeOffset.UtcNow-DateTimeOffset.Parse(a.S("opens_at"))).TotalHours);if(a.N("attempt")<2&&rvh>.25&&b.S("status")=="DistressedLiquidation")OpenAuction(tx,b,(int)a.N("attempt")+1,a.S("id"),rvh);else Audit(tx,"manual_intervention_required",b.S("id"),"No award; retries exhausted or life budget unavailable.","critical");}
 public void Sweep()=>store.Write(tx=>{foreach(var a in tx.All("auction").Where(a=>a.S("status") is "Open" or "AwaitingConfirmation")){var b=tx.Need("batch",a.S("batch_id"));var deadline=a.S(a.S("status")=="Open"?"closes_at":"confirmation_deadline");if(b.S("status")!="DistressedLiquidation"||DateTimeOffset.Parse(deadline)<=DateTimeOffset.UtcNow)Retry(tx,a,b,"Deadline elapsed or batch unavailable");}return true;});
 public object Delivery(string lot,JsonObject p,Actor actor)=>store.Write(tx=>{var old=tx.Get("delivery",lot);if(old is not null){J.Require(old.S("external_reference")==p.S("external_reference")&&old.N("received_kg")==p.N("received_kg")&&old.S("evidence_note")==p.S("evidence_note"),"Conflicting delivery assertion",409);return new{status="already_reported",independently_verified=false};}var b=tx.Need("batch",lot);J.Require(b.S("status")=="Cleared","Settled award required",409);var s=tx.Need("settlement",lot);J.Require(Math.Abs(s.N("kg_cleared")-p.N("received_kg"))<.001&&p.S("external_reference").Length>=8&&p.S("evidence_note").Length>=20,"Receipt requires full lot and evidence; discrepancies require dispute review");J.Require(!tx.All("delivery").Any(x=>x.S("external_reference")==p.S("external_reference")),"Receipt reference reused",409);p["recorded_by"]=actor.Subject;p["confirmed_at"]=J.Now();tx.Put("delivery",lot,p);var buyer=tx.Need("buyer",s.S("buyer_id"));buyer["capacity_kg"]=buyer.N("capacity_kg")+s.N("kg_cleared");tx.Put("buyer",buyer.S("id"),buyer);b["status"]="RescueDeliveryReported";tx.Put("batch",lot,b);Audit(tx,"delivery_reported",lot,"Operator-reported receipt; capacity released once; not independently verified.");return new{status="reported",independently_verified=false};});
}
